// Channel-agnostic envelope (AI Finance Inbox implementation plan, Phase 1)
// -- only this node and the reply-formatting/Slack nodes below know Slack's
// payload shape. Everything from "Build Router Input" onward receives a
// shape any future front door (Telegram, WhatsApp, Retell, OCR, Web Chat)
// could produce identically.
//
// SlackTrigger's webhook() handler returns `req.body.event` directly as the
// item's json (confirmed by reading SlackTrigger.node.js in this exact n8n
// version) -- there is no `.event` wrapper here, unlike EYAN's own signed
// webhooks in workflows/crm/.
const event = $json;

const attachments = Array.isArray(event.files)
  ? event.files.map((file) => ({
      url: file.url_private || null,
      mimeType: file.mimetype || null,
      name: file.name || null,
    }))
  : [];

return [{
  json: {
    // Channel-agnostic request -- forwarded to the Finance Intent Router
    // unchanged (see "Build Router Input"). No intent classification, no
    // Finance-specific validation happens here or anywhere in this workflow.
    channel: 'slack',
    externalUserId: event.user || null,
    externalMessageId: event.event_ts || event.ts || null,
    rawText: event.text || '',
    attachments,
    receivedAt: new Date().toISOString(),
    // Slack-specific reply-routing info -- kept here only, never forwarded
    // past "Build Router Input" below. Used later by "Format Slack Reply" /
    // "Slack - Post Reply" to know where to send the response, referenced
    // by node name ($('Normalize Slack Input')) rather than threaded through
    // the Router's input/output.
    slackChannelId: event.channel || null,
    slackThreadTs: event.thread_ts || event.ts || null,
  },
}];

// $execution.id is n8n's own execution ID for THIS (the front-door)
// execution -- generated exactly once, here, and threaded UNCHANGED through
// every subsequent Execute Workflow hop (the Finance Intent Router, and
// whichever intent handler the Router dispatches to in turn). It must never
// be regenerated at a later hop: $execution.id read inside a downstream
// workflow would be that workflow's OWN, different execution ID, which
// would silently break the idempotency check every Finance write endpoint
// relies on (see eyan-ai-platform ADR-0024, and the AI Finance Inbox
// implementation plan's idempotency-threading note).
const normalized = $('Normalize Slack Input').item.json;

return [{
  json: {
    contractVersion: '1',
    workflowExecutionId: $execution.id,
    workflowName: '01-finance-inbox-entry',
    channel: normalized.channel,
    externalUserId: normalized.externalUserId,
    externalMessageId: normalized.externalMessageId,
    rawText: normalized.rawText,
    attachments: normalized.attachments,
  },
}];

// Generic pass-through formatting only -- this node never inspects intent,
// category, amount, or any Finance-specific field (per this workflow's
// scope: normalize, generate the execution ID, route, reply -- nothing
// else). The Finance Intent Router (and whichever handler it dispatches to)
// is solely responsible for producing a human-readable `message`; this
// node's only job is picking a safe fallback when that response is missing
// or the call itself failed -- e.g. the Router doesn't exist yet (this
// phase), or errored. "Call Finance Intent Router" has onError:
// continueRegularOutput set, so a failed call surfaces as $json.error here
// rather than crashing the execution -- same pattern as
// workflows/crm/03-ai-qualification.json's "Map AI Core Result" reading
// $json.error after "Call AI Core".
const result = $json || {};

let replyText;
if (result.error) {
  const message = String((result.error && result.error.message) || result.error);
  replyText = "Sorry, I couldn't process that just now. Please try again in a moment.";
  console.log(`[Format Slack Reply] Finance Intent Router call failed: ${message}`);
} else if (typeof result.message === 'string' && result.message.trim()) {
  replyText = result.message;
} else {
  replyText = "Sorry, I couldn't process that just now. Please try again in a moment.";
}

return [{ json: { replyText } }];
